    "Overlay nativo TP": "Native TP overlay",
    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "Compatible with all versions (Universal Overlay for Vanilla/OptiFine/Forge + Extended integration with TP Companion in Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · Window or borderless · Right Shift / F8 opens the editor. If you use exclusive F11, return to window mode first.",
    "Desactivar HUD universal": "Disable universal HUD",
    "Activar HUD universal": "Enable universal HUD",
    "Integración extendida · TP Companion": "Extended integration · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "Live HUD for FPS, coordinates, direction, armor, keys, ping and time. Includes a consistent HUD font, transparent menu, zoom with C, a surface minimap and chat timestamps.",
    "Instalar el complemento TP al preparar una instancia compatible": "Install the TP add-on when preparing a compatible instance",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "Current adapter: Fabric 1.21.1. In other versions, the universal overlay is used. FPS and position connect to TP Bridge at startup, without admin permissions. Availability of other data is indicated by module; the minimap and engine functions require TP Companion compatible.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "The add-on is not included in this installation. Update TP LAUNCHER to enable it.",
    "Datos del juego": "Game data",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "The connector is ready. Activate HUD before opening Minecraft.",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "This installation does not include the HUD connector. Update TP LAUNCHER to enable game data.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "Start Minecraft from TP to receive data. F8 and right Shift open the editor.",
    "Esperando partida": "Waiting for game",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "External effects are prepared for the next launch with credit to their authors. TP only enables or disables JARs it installed and verified. Manage manually added mods in the content studio.",
