    ". Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.": ". Players, icon, and message are checked in the cloud. Each card date indicates the age of the data; «Measure ping» performs a TCP connection from your device only when you press it.",
