    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API is a public, free query catalog, subject to availability and usage limits. If it doesn't respond, only a previously saved page from TP API can be displayed, identified as such. There is no universal registry of all servers.",
