    "Perfil social y cosméticos": "Social Profile and Cosmetics",
    "Enlaces de": "Links to",
    ", guardados localmente. No se conectan cuentas ni se verifica su titularidad.": ", saved locally. Accounts are not connected and ownership is not verified.",
    "Guardar perfil": "Save Profile",
