    "Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.": "As otimizações selecionadas são resolvidas para a versão exata e carregador; escolher um Release Vanilla com otimizadores ativos prepara uma instalação independente Fabric. Nenhuma melhoria de FPS fixa é promessa.",
