    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHER é um projeto independente da TP LABS. Não é um produto oficial da Minecraft nem aprovado ou associado a Mojang, Microsoft ou as comunidades vinculadas.",
    "Términos y condiciones": "Termos e condições",
    "Créditos y licencias de terceros": "Créditos e licenças de terceiros",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric, Forge, OptiFine, Modrinth e CurseForge identificam projetos e provedores integrados. Os logotipos e marcas registradas pertencem a seus respectivos detentores; eles não fazem parte do arte original da TP. NeoForge: Equipe NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan e colaboradores · SIL OFL 1.1. Visualizador 3D: skinview3d e Three.js · MIT.",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11; logotipo usado como crédito e link de acordo com suas diretrizes públicas. Microsoft, GitHub e Discord identificam seus serviços. Seus marcas registradas pertencem a seus detentores; sua presença não implica patrocínio ou afiliação.",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "As licenças CC BY 4.0 e CC0 mencionadas aqui se referem ao direito de autor do material indicado e excluem os direitos de marca. Os créditos não substituem as autorizações específicas que possam se aplicar.",
