    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "Compatível com todas as versões (Sobreposição Universal para Vanilla/OptiFine/Forge + Integração estendida com TP Companion em Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · Janela ou sem bordas · Shift Direito / F8 abre o editor. Se você usar F11 exclusivo, retorne ao modo de janela primeiro.",
