    "Integración extendida · TP Companion": "Integração estendida · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "Live HUD para FPS, coordenadas, direção, armadura, teclas, ping e tempo. Inclui uma fonte HUD consistente, menu transparente, zoom com C, um mini mapa de superfície e timestamps de chat.",
    "Instalar el complemento TP al preparar una instancia compatible": "Instale o complemento TP quando preparar uma instância compatível",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "Adaptador atual: Fabric 1.21.1. Em outras versões, o overlay universal é usado. FPS e posição se conectam ao TP Bridge no início, sem permissões de administrador. A disponibilidade de outros dados é indicada pelo módulo; o mini mapa e as funções do motor exigem TP Companion compatível.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "O complemento não está incluído nesta instalação. Atualize TP LAUNCHER para habilitá-lo.",
