    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "Esta instalação não inclui o conector HUD. Atualize TP LAUNCHER para habilitar os dados do jogo.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "Inicie Minecraft do TP para receber dados. F8 e Shift direito abrem o editor.",
    "Esperando partida": "Aguarde o jogo",
