    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API é um catálogo de consulta público e gratuito, sujeito a limites de disponibilidade e uso. Se não responder, apenas uma página salva anteriormente do TP API pode ser exibida, identificada como tal. Não há registro universal de todos os servidores.",
