    "· Lead Dev · TP LABS. Para soporte, privacidad, atribuciones o solicitudes de titulares de derechos:": "· Chefe de Desenvolvimento · TP LABS. Para suporte, privacidade, atribuições ou solicitações de proprietários de direitos autorais:",
