    "Esta página explica el funcionamiento y atribuciones del proyecto; no certifica permisos generales sobre materiales de terceros. Si detectas un problema de derechos, incluye el recurso y su ubicación al contactar.": "Esta página explica a funcionalidade e atribuições do projeto; ela não certifica permissões gerais sobre materiais de terceiros. Se detectar um problema de direitos autorais, inclua o recurso e seu local ao entrar em contato.",
