    "Términos y condiciones": "Conditions d'utilisation",
    "Créditos y licencias de terceros": "Crédits et licences tierces",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric, Forge, OptiFine, Modrinth et CurseForge identifient des projets et fournisseurs intégrés. Les logos et marques déposées appartiennent à leurs détenteurs respectifs ; ils ne forment pas partie de l'art original de TP. NeoForge: NeoForged team · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan et collabos · SIL OFL 1.1. 3D Viewer: skinview3d et Three.js · MIT.",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11 ; le logo est utilisé comme crédit et lien conformément à leurs lignes directrices publiques. Microsoft, GitHub et Discord identifient leurs services. leurs marques déposées appartiennent à leurs détenteurs respectifs ; leur présence ne suggère pas de sponsorship ou d'affiliation.",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "Les licences CC BY 4.0 et CC0 citées ici font référence au droit d'auteur du matériel indiqué et excluent les droits de marque. Les crédits ne remplacent pas les autorisations spécifiques qui pourraient s'appliquer.",
