    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "Compatible avec toutes les versions (Superposition universelle pour Vanilla/OptiFine/Forge + Intégration étendue avec TP Companion dans Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · Fenêtre ou sans bordure · Shift Droit / F8 ouvre l'éditeur. Si tu utilises F11 exclusif, retourne en mode fenêtre d'abord.",
    "Desactivar HUD universal": "Désactiver l'intégration universelle HUD",
    "Activar HUD universal": "Activer l'intégration universelle HUD",
    "Integración extendida · TP Companion": "Intégration étendue · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "Live HUD pour FPS, coordonnées, direction, armure, touches, ping et heure. Inclut une police HUD cohérente, un menu transparent, un zoom avec C, une mini-carte de surface et des horodatages de chat.",
    "Instalar el complemento TP al preparar una instancia compatible": "Installer le module TP lors de la préparation d'une instance compatible",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "Adapter actuel : Fabric 1.21.1. Dans d'autres versions, l'overlay universel est utilisé. FPS et position se connectent au démarrage à TP Bridge, sans permissions administratives. La disponibilité d'autres données est indiquée par le module ; la mini-carte et les fonctions de moteur nécessitent TP Companion compatible.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "Le module n'est pas inclus dans cette installation. Mettez à jour TP LAUNCHER pour l'activer.",
    "Datos del juego": "Données du jeu",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "Le connecteur est prêt. Activez HUD avant d'ouvrir Minecraft.",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "Cette installation ne comprend pas le connecteur HUD. Mettez à jour TP LAUNCHER pour activer les données du jeu.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "Démarrez Minecraft à partir de TP pour recevoir les données. F8 et Shift droit ouvrent l'éditeur.",
    "Esperando partida": "En attente du jeu",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "Les effets externes sont préparés pour le prochain lancement, à l'honneur de leurs auteurs. TP active ou désactive uniquement les JARs qu'il a installés et vérifiés. Gérez les mods ajoutés manuellement dans le studio de contenu.",
