    "Solo se equipan objetos con modelos y texturas locales de esta versión; siguen las manos y se incluyen en el PNG. Los recursos ausentes quedan ocultos.": "Seulement les objets avec des modèles et des textures locales de cette version sont équipés ; ils suivent les mains et sont inclus dans le PNG. Les ressources manquantes sont cachées.",
