    "Ir a": "Aller à",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API est un catalogue de requêtes public et gratuit, soumis aux limites d'accessibilité et d'utilisation. Si elle ne répond pas, seule une page enregistrée précédemment de l'API TP peut être affichée, identifiée comme telle. Il n'y a pas de registre universel de tous les serveurs.",
