    "Para pantalla exclusiva F11, vuelve primero al modo ventana. Los módulos del juego requieren un adaptador compatible.": "Für exklusiven Fenstermodus F11, kehre zu Fenstermodus zurück. Spielmodule benötigen ein kompatibles Adapter.",
