    "Se aplica dentro del juego cuando el conector o mod de esta edición lo permite. No es un widget que se coloque en pantalla.": "Wird innerhalb des Spiels angewendet, wenn das Verbindungsmodul oder mod unterstützt. Dies ist kein Bildschirmwidget.",
