    "Packs, shaders y control rápido": "Packs, shaders und schnelle Steuerungen",
    "Los cambios se aplican al proceso de Minecraft abierto. La compatibilidad se confirma con su adaptador.": "Änderungen werden auf den laufenden Minecraft-Prozess angewendet. Sein Adapter bestätigt die Kompatibilität.",
    "Control de niebla": "Nebelsteuerung",
    "Desactivar niebla en entornos seleccionados": "Deaktiviere den Nebel in ausgewählten Umgebungen",
    "Reducción de niebla": "Nebelreduktion",
    "Se aplica en vivo mediante los hooks de render compatibles. Los shaders que usan su propia niebla pueden requerir un adaptador específico.": "Wendet sich in Echtzeit durch kompatible Renderhooks. shaders, die ihren eigenen Nebel verwenden, können einen spezifischen Adapter benötigen.",
    "TP Turbo · próximo inicio": "TP Turbo · nächste Start",
    "Ajustes de recolección G1GC para Java 8 o superior": "G1GC-Garbage Collection-Einstellungen für Java 8 oder neuer",
    "Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.": "Die gewählten Optimierungen werden für die genaue Version und den Loader aufgelöst; das Wählen eines Release Vanilla mit aktivierten Optimierern bereitet eine unabhängige Fabric-Installation vor. Keine feste FPS-Steigerung wird versprochen.",
    "Gráficos y audio": "Grafik und Audio",
    "El brillo respeta el rango admitido por el juego; no se promete Fullbright con una opción que Minecraft limita.": "Helligkeit respektiert den Bereich, der vom Spiel erlaubt wird; keine Fullbright wird mit einer Option versprochen, die Minecraft begrenzt.",
    "Cambio rápido de servidor": "Schnelle Serverwechsel",
