    "Los atajos devuelven el foco al juego. Algunos no existen en versiones antiguas. La JVM puede ignorar una solicitud de memoria.": "Verknüpfungen bringen den Fokus zurück zum Spiel. Einige sind in älteren Versionen nicht verfügbar. Der JVM ignoriert möglicherweise eine Garbage Collection-Anfrage.",
