    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHER ist ein unabhängiges Projekt von TP LABS. Es ist kein offizielles Produkt von Minecraft und wird nicht von Mojang, Microsoft oder den verlinkten Gemeinschaften genehmigt oder verbunden.",
    "Términos y condiciones": "Nutzungsbedingungen",
    "Créditos y licencias de terceros": "Drittparteikredit und Lizenz",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric, Forge, OptiFine, Modrinth und CurseForge identifizieren integrierte Projekte und Anbieter. Die Logos und Markenrechte gehören ihren jeweiligen Eigentümern; sie bilden nicht Teil der ursprünglichen TP-Kunst. NeoForge: NeoForged Team · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan und Kollegen · SIL OFL 1.1. 3D Viewer: skinview3d und Three.js · MIT.",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11; das Logo wird nach ihren öffentlichen Richtlinien als Kredit und Link verwendet. Microsoft, GitHub und Discord identifizieren ihre Dienste. Ihre Markenrechte gehören ihren Eigentümern; ihre Anwesenheit impliziert keine Sponsoring oder Verbindung.",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "Die hier zitierten CC BY 4.0 und CC0-Lizenzen beziehen sich auf das Urheberrecht des angegebenen Materials und schließen Markenrechte aus. Die Kredite ersetzen keine spezifischen Genehmigungen, die anwenden können.",
    "Licencias y fuentes": "Lizenzen und Quellen",
