    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "Kompatibel mit allen Versionen (Universeller Overlay für Vanilla/OptiFine/Forge + Erweiterte Integration mit TP Companion in Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · Fenster oder ohne Rahmen · Rechte Shift / F8 öffnet den Editor. Wenn du ausschließlich F11 verwendest, wechsle zunächst in den Fenstermodus.",
    "Desactivar HUD universal": "Deaktiviere universelle HUD",
    "Activar HUD universal": "Aktiviere universelle HUD",
    "Integración extendida · TP Companion": "Erweiterte Integration · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "Lebendige HUD für FPS, Koordinaten, Richtung, Rüstung, Tasten, Ping und Uhrzeit. Enthält ein konsistentes HUD-Schriftzug, transparentes Menü, Zoom mit C, eine Oberflächen-Miniaturkarte und Chat-Zeitstempel.",
    "Instalar el complemento TP al preparar una instancia compatible": "Installiere das TP-Add-On beim Vorbereiten einer kompatiblen Instanz",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "Aktuelles Adapter: Fabric 1.21.1. In anderen Versionen wird der universelle Overlays verwendet. FPS und Position verbinden sich beim Start mit TP Bridge, ohne Admin-Berechtigungen. Verfügbarkeit anderer Daten wird durch das Modul angezeigt; die Miniaturkarte und die Enginefunktionen erfordern TP Companion-kompatibel.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "Das Add-On ist nicht in dieser Installation enthalten. Aktualisiere TP LAUNCHER, um es zu aktivieren.",
    "Datos del juego": "Spiel-Daten",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "Der Connector ist bereit. Aktiviere HUD, bevor Minecraft geöffnet wird.",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "Diese Installation enthält den HUD-Connector nicht. Aktualisiere TP LAUNCHER, um Spiel-Daten zu aktivieren.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "Starte Minecraft von TP, um Daten zu erhalten. F8 und rechte Shift öffnen den Editor.",
    "Esperando partida": "Warte auf das Spiel",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "Externe Effekte werden für den nächsten Start vorbereitet, mit Dank an ihre Autoren. TP aktiviert oder deaktiviert nur die JARs, die es installiert und überprüft hat. Verwalte manuell hinzugefügte mods im Inhaltsstudio.",
