    "Solo se equipan objetos con modelos y texturas locales de esta versión; siguen las manos y se incluyen en el PNG. Los recursos ausentes quedan ocultos.": "Nur Objekte mit lokalen Modellen und Texturen dieser Version werden ausgerüstet; sie folgen den Händen und sind in der PNG enthalten. Fehlende Ressourcen werden ausgeblendet.",
