    ". Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.": ". Spieler, Icon und Nachricht werden in der Cloud überprüft. Jede Karte Datum gibt die Alter der Daten an; «Ping messen» führt eine TCP-Verbindung von deinem Gerät nur dann durch, wenn du darauf drückst.",
