    "Ir a": "Gehe zu",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API ist ein öffentlicher, kostenloses Abfragekatalog, der Verfügbarkeit und Nutzungslimits unterliegt. Wenn er nicht antwortet, kann nur eine zuvor gespeicherte Seite aus der TP API angezeigt werden, die als solche gekennzeichnet ist. Es gibt keine universelle Registrierung aller Server.",
