    "MyMemory traduce textos públicos en inglés. Sin conexión o al alcanzar el límite gratuito se muestra el original.": "MyMemory übersetzt öffentliche englische Texte in deine Sprache. Ohne Verbindung oder bei erreichtem kostenlosen Kontingent wird das Original angezeigt.",
