    "Esta página explica el funcionamiento y atribuciones del proyecto; no certifica permisos generales sobre materiales de terceros. Si detectas un problema de derechos, incluye el recurso y su ubicación al contactar.": "Diese Seite erklärt die Funktionalität und Zitate des Projekts; sie bestätigt keine allgemeinen Rechte über Drittmaterialien. Wenn Sie ein Rechtsproblem feststellen, beinhalten Sie die Ressource und ihren Standort bei der Kontaktaufnahme.",
