    "Se aplica en vivo mediante los hooks de render compatibles. Los shaders que usan su propia niebla pueden requerir un adaptador específico.": "Применяется в реальном времени через совместимые хуки рендеринга. shaders, которые используют собственный туман, могут требовать специального адаптера.",
    "TP Turbo · próximo inicio": "Турбо-перемещение · следующий запуск",
    "Ajustes de recolección G1GC para Java 8 o superior": "Настройки сборки G1GC для Java 8 или новее",
    "Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.": "Выбранные оптимизации решены для точной версии и загрузчика; выбор Release Vanilla с активными оптимизаторами подготовит независимую установку Fabric. Нет гарантии увеличения FPS.",
