    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHER является независимым проектом TP LABS. Он не является официальным продуктом Minecraft и не одобрен или связан с Mojang, Microsoft или связанными сообществами.",
