    "Créditos y licencias de terceros": "Сотрудничество и лицензии сторонних разработчиков",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric, Forge, OptiFine, Modrinth и CurseForge идентифицируют интегрированные проекты и поставщиков. Логотипы и товарные знаки принадлежат их владельцам; они не являются частью оригинальной работы TP. NeoForge: NeoForged команда · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan и коллеги · SIL OFL 1.1. 3D Viewer: skinview3d и Three.js · MIT.",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11; логотип используется как кредит и ссылка в соответствии с их публичными руководствами. Microsoft, GitHub и Discord идентифицируют их услуги. Их товарные знаки принадлежат их владельцам; их присутствие не подразумевает спонсорство или аффилиацию.",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "CC BY 4.0 и CC0 лицензии, упомянутые здесь, относятся к авторскому праву указанного материала и исключают права на товарные знаки. Кредиты не заменяют конкретные авторизации, которые могут применяться.",
