    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "Совместим с всеми версиями (Универсальный оверлей для Vanilla/OptiFine/Forge + Расширенная интеграция с TP Companion в Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · Окно или без рамки · Правый Shift / F8 открывает редактор. Если вы используете исключительный F11, сначала вернитесь в режим окна.",
    "Desactivar HUD universal": "Отключить универсальный HUD",
    "Activar HUD universal": "Включить универсальный HUD",
    "Integración extendida · TP Companion": "Расширенная интеграция · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "Живой HUD для FPS, координат, направления, брони, клавиш, пинга и времени. Включает в себя постоянный шрифт HUD, прозрачное меню, масштабирование с помощью C, поверхность миникарты и временные метки чата.",
    "Instalar el complemento TP al preparar una instancia compatible": "Установите дополнение TP при подготовке совместимой экземпляра",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "Текущий адаптер: Fabric 1.21.1. В других версиях используется универсальный оверлей. FPS и позиция подключаются к TP Bridge при запуске, без прав администратора. Доступность других данных указывается модулем; миникарта и функции движка требуют совместимости с TP Companion.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "Дополнение не включено в эту установку. Обновите TP LAUNCHER для включения его функций.",
    "Datos del juego": "Данные игры",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "Подключение готово. Активируйте HUD перед открытием Minecraft.",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "Эта установка не включает в себя HUD-соединитель. Обновите TP LAUNCHER для включения данных игры.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "Запустите Minecraft из TP для получения данных. F8 и правый Shift открывают редактор.",
    "Esperando partida": "Ожидание игры",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "Внешние эффекты подготовлены для следующего запуска с благодарностью их авторам. TP только включает или отключает JARы, которые он установил и проверил. Управляйте вручную добавленными mods в студии контента.",
