    "· última página guardada": "· последняя страница сохранена",
    ". Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.": ". Игроки, значок и сообщение проверяются в облаке. Каждая дата на карточке указывает на возраст данных; «Измерить пинг» выполняет TCP-соединение с вашего устройства только при нажатии.",
