    "Ir a": "Перейти к",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API - это публичный, бесплатный каталог запросов, подлежащий ограничениям доступности и использования. Если он не отвечает, можно отобразить только ранее сохраненную страницу из TP API, идентифицируемую как таковая. Нет универсального реестра всех серверов.",
