    "MyMemory traduce textos públicos en inglés. Sin conexión o al alcanzar el límite gratuito se muestra el original.": "MyMemory переводит публичные тексты с английского на выбранный язык. Без подключения или при исчерпании бесплатного лимита показывается оригинал.",
