    "Perfil local sin cuenta Microsoft. No accede a servidores premium.": "Локальный профиль без аккаунта Microsoft. Не имеет доступа к премиум-серверам.",
    "Microsoft · Minecraft Premium": "Microsoft · Minecraft Премиум",
