    "Esta página explica el funcionamiento y atribuciones del proyecto; no certifica permisos generales sobre materiales de terceros. Si detectas un problema de derechos, incluye el recurso y su ubicación al contactar.": "Эта страница объясняет функциональность и атрибуции проекта; она не свидетельствует об общих правах на материалы сторонних лиц. Если вы обнаруживаете проблему с правами, включите ресурс и его местоположение при контакте.",
