    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHER è un progetto indipendente di TP LABS. Non è un prodotto ufficiale di Minecraft né è approvato o associato a Mojang, Microsoft o le comunità linkate.",
    "Términos y condiciones": "Termini e condizioni",
    "Créditos y licencias de terceros": "Crediti e licenze di terze parti",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric, Forge, OptiFine, Modrinth e CurseForge identificano progetti e fornitori integrati. I loghi e i marchi di bandiera appartengono ai rispettivi proprietari; non fanno parte dell'arte originale di TP. NeoForge: NeoForged team · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan e collaboratori · SIL OFL 1.1. 3D Viewer: skinview3d e Three.js · MIT.",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11; logo utilizzato come crediti e link secondo le loro linee pubbliche. Microsoft, GitHub e Discord identificano i loro servizi. I loro marchi di bandiera appartengono ai rispettivi proprietari; la loro presenza non implica sponsorizzazione o affiliazione.",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "Le licenze CC BY 4.0 e CC0 menzionate qui si riferiscono al diritto d'autore del materiale indicato e escludono i diritti di marchio. I crediti non sostituiscono le autorizzazioni specifiche che potrebbero essere applicabili.",
