    "Overlay nativo TP": "Overlay TP nativo",
    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "Compatibile con tutte le versioni (Overlay universale per Vanilla/OptiFine/Forge + Integrazione estesa con TP Companion in Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · Finestra o senza bordi · Shift Destro / F8 apre l'editor. Se usi F11 esclusivo, torna al modalità finestra prima.",
    "Desactivar HUD universal": "Disabilita l'overlay universale HUD",
    "Activar HUD universal": "Abilita l'overlay universale HUD",
    "Integración extendida · TP Companion": "Integrazione estesa · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "Live HUD per FPS, coordinate, direzione, armatura, tasti, ping e ora. Include un font HUD costante, menu trasparente, zoom con C, una minimappa superficiale e timestamp del chat.",
    "Instalar el complemento TP al preparar una instancia compatible": "Installa l'aggiunto TP quando prepari un'istanza compatibile",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "Adapter attuale: Fabric 1.21.1. In altre versioni, viene usato l'overlay universale. FPS e posizione si connettono a TP Bridge all'avvio, senza permessi di amministratore. L'accessibilità di altri dati è indicata dal modulo; la minimappa e le funzioni del motore richiedono TP Companion compatibile.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "L'aggiunto non è incluso in questa installazione. Aggiorna TP LAUNCHER per abilitarlo.",
    "Datos del juego": "Dati del gioco",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "Il connettore è pronto. Attiva HUD prima di aprire Minecraft.",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "Questa installazione non include il connettore HUD. Aggiorna TP LAUNCHER per abilitare i dati del gioco.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "Avvia Minecraft da TP per ricevere i dati. F8 e Shift destro aprono l'editor.",
    "Esperando partida": "Aspetta il gioco",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "Effetti esterni sono pronti per la prossima avvio con crediti agli autori. TP abilita o disabilita solo i JAR che ha installato e verificato. Gestisci manualmente i mods aggiunti nel studio del contenuto.",
