    "Solo se equipan objetos con modelos y texturas locales de esta versión; siguen las manos y se incluyen en el PNG. Los recursos ausentes quedan ocultos.": "Solo gli oggetti con modelli e texture locali di questa versione sono equipaggiati; seguono le mani e sono inclusi nel PNG. Le risorse mancanti vengono nascoste.",
