    ". Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.": ". I giocatori, l'icona e il messaggio vengono controllati nel cloud. Ogni data sulla scheda indica l'età dei dati; «Misura ping» esegue una connessione TCP dal tuo dispositivo solo quando la premo.",
