    "Ir a": "Vai a",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API è un catalogo di query pubblico e gratuito, soggetto ai limiti di disponibilità e utilizzo. Se non risponde, può essere visualizzato solo una pagina salvata precedentemente dal TP API, identificata come tale. Non esiste un registro universale di tutti i server.",
