    "MyMemory traduce textos públicos en inglés. Sin conexión o al alcanzar el límite gratuito se muestra el original.": "MyMemory traduce i testi pubblici in inglese nella tua lingua. Senza connessione o al raggiungimento della quota gratuita viene mostrato il testo originale.",
