    "Esta página explica el funcionamiento y atribuciones del proyecto; no certifica permisos generales sobre materiales de terceros. Si detectas un problema de derechos, incluye el recurso y su ubicación al contactar.": "Questa pagina spiega la funzionalità e le attribuzioni del progetto; non garantisce diritti generali su materiali di terze parti. Se rilevi un problema di diritti, includi la risorsa e la sua posizione quando ti contatta.",
