    "Reducción de niebla": "雾减少",
    "Se aplica en vivo mediante los hooks de render compatibles. Los shaders que usan su propia niebla pueden requerir un adaptador específico.": "通过兼容的渲染钩实时应用。使用自己雾的shaders可能需要特定显卡。",
    "TP Turbo · próximo inicio": "TP加速器·下次启动",
    "Ajustes de recolección G1GC para Java 8 o superior": "Java 8或更新版本的G1GC垃圾收集设置",
    "Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.": "所选优化针对确切版本和加载器解决；选择一个带有活动优化器的Release原版将准备一个独立的Fabric安装。不保证固定的FPS增加。",
    "Gráficos y audio": "图形和音频",
    "El brillo respeta el rango admitido por el juego; no se promete Fullbright con una opción que Minecraft limita.": "亮度尊重游戏允许的范围；不保证在Minecraft限制的选项下有全光。",
