    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHER是TP工作室的独立项目。它不是Minecraft的官方产品，也不被批准或与Mojang、Microsoft或相关社区关联。",
    "Términos y condiciones": "条款和条件",
    "Créditos y licencias de terceros": "第三方信用和许可证",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric、Forge、OptiFine、Modrinth和CurseForge标识集成项目和提供商。这些标志和商标属于各自的持有者；它们不构成TP原创艺术的一部分。NeoForge：NeoForged团队 · CC BY 4.0。Quilt：QuiltMC/art · CC0 1.0。Monocraft：Idrees Hassan及其合作者 · SIL OFL 1.1。3D查看器：skinview3d和Three.js · MIT。",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11；根据他们的公开指南，标志用作信用和链接。Microsoft、GitHub和Discord标识他们的服务。他们的商标属于各自的持有者；他们的存在不意味着赞助或关联。",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "这里引用的CC BY 4.0和CC0许可证指的是所指材料的版权，并排除商标权。信用不代替可能适用的特定授权。",
