    "Organiza tus herramientas y prepara cada instalación a tu manera.": "组织你的工具并按你自己的方式准备每个安装。",
    "Abrir editor de HUD": "打开HUD编辑器",
    "seleccionados ·": "已选中 ·",
    "Overlay nativo TP": "本地TP覆盖层",
    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "与所有版本兼容（通用覆盖层适用于原版/OptiFine/Forge + 在Fabric中与TP Companion的扩展集成）。",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · 窗口或无边框 · 右Shift / F8打开编辑器。如果你使用独占F11，请先返回窗口模式。",
    "Desactivar HUD universal": "禁用通用HUD",
    "Activar HUD universal": "启用通用HUD",
    "Integración extendida · TP Companion": "扩展集成 · TP Companion",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "实时HUD显示FPS、坐标、方向、盔甲、按键、延迟和时间。包括一致的HUD字体、透明菜单、使用C键缩放、表面迷你地图和聊天时间戳。",
    "Instalar el complemento TP al preparar una instancia compatible": "在准备兼容实例时安装TP插件",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "当前适配器：Fabric 1.21.1。在其他版本中使用通用覆盖层。FPS和位置在启动时连接到TP Bridge，无需管理员权限。其他数据的可用性由模块指示；迷你地图和引擎功能需要TP Companion兼容。",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "插件未包含在本安装中。更新TP LAUNCHER以启用它。",
    "Datos del juego": "游戏数据",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "连接器已就绪。在打开Minecraft之前激活HUD。",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "本安装不包含HUD连接器。更新TP LAUNCHER以启用游戏数据。",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "从TP启动Minecraft以接收数据。F8和右Shift打开编辑器。",
    "Esperando partida": "等待游戏",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "外部效果将在下次启动时准备，并感谢作者。TP仅启用或禁用它安装和验证的JAR文件。手动添加的mods在内容工作室中进行管理。",
