    "Solo se equipan objetos con modelos y texturas locales de esta versión; siguen las manos y se incluyen en el PNG. Los recursos ausentes quedan ocultos.": "只有具有此版本本地模型和纹理的对象才会装备；它们会跟随手部，并包含在PNG中。缺少资源会被隐藏。",
