    ". Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.": ". 玩家、图标和消息在云中检查。每张卡片的日期表示数据的年龄；“测量延迟”仅在你按下时从你的设备执行 TCP 连接。",
