    "Ir a": "前往",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API是一个公开的、免费的查询目录，受可用性和使用限制。如果它没有响应，只能显示TP API的之前保存的页面，标识为如此。没有所有服务器的通用注册表。",
