    "Pantalla completa sin bordes": "境界線なしフルスクリーン",
    "Para pantalla exclusiva F11, vuelve primero al modo ventana. Los módulos del juego requieren un adaptador compatible.": "排他フルスクリーン F11 で戻る。ゲームモジュールには互換性のあるアダプターが必要です。",
