    "Mod externo: se prepara al iniciar una versión compatible. Sus opciones internas se ajustan en Minecraft.": "外部mod: 兼容バージョンを起動すると準備されます。その設定をMinecraftで構成します。",
    "Mantén": "ズームする",
    "para hacer zoom y suéltala para recuperar la vista normal. Funciona cuando el adaptador de esa versión está conectado.": "releaseで通常のビューに戻ります。そのバージョンのアダプターが接続されている場合に機能します。",
    "Se aplica dentro del juego cuando el conector o mod de esta edición lo permite. No es un widget que se coloque en pantalla.": "このエディションのコンセクターやmodによってサポートされた場合、ゲーム内に適用されます。これは画面ウィジェットではありません。",
