    "Estos controles solo cambian": "これらのコントロールは",
    "Packs, shaders y control rápido": "パック、shaders、およびクイックコントロールのみ",
    "Los cambios se aplican al proceso de Minecraft abierto. La compatibilidad se confirma con su adaptador.": "変更は実行中のMinecraftプロセスに適用されます。そのアダプターは互換性を確認します。",
    "Control de niebla": "霧の制御",
    "Desactivar niebla en entornos seleccionados": "選択された環境で霧を無効化",
    "Reducción de niebla": "霧の減少",
    "Se aplica en vivo mediante los hooks de render compatibles. Los shaders que usan su propia niebla pueden requerir un adaptador específico.": "互換性のあるレンダーハックを通じてリアルタイムで適用されます。shadersが独自の霧を使用している場合、特定のアダプターが必要かもしれません。",
    "TP Turbo · próximo inicio": "TPターボ · 次回起動",
    "Ajustes de recolección G1GC para Java 8 o superior": "Java 8 またはそれ以上用の G1GC ガベージコレクション設定",
    "Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.": "選択された最適化は正確なバージョンとローダーに対して解決されます。Release ヴァンパイアを有効な最適化で選択すると、独立した Fabric インストールが準備されます。固定の FPS 増加は保証されません。",
    "Gráficos y audio": "グラフィックスと音楽",
    "El brillo respeta el rango admitido por el juego; no se promete Fullbright con una opción que Minecraft limita.": "明るさはゲームが許可する範囲内に保たれます。Minecraft が制限するオプションを選択すると、フルブライトは保証されません。",
    "Cambio rápido de servidor": "クイックサーバー変更",
    "Conectar sale de la partida actual. Requiere TP Companion compatible.": "現在のゲームを切断します。互換性のあるTP Companionが必要です。",
