    "Los atajos devuelven el foco al juego. Algunos no existen en versiones antiguas. La JVM puede ignorar una solicitud de memoria.": "ショートカットはゲームに焦点を戻します。一部は古いバージョンでは利用できません。JVMはガベージコレクションリクエストを無視する可能性があります。",
    "Paquetes de recursos": "リソースパック",
    "La prioridad más alta aparece al final de la lista.": "最も優先度の高いものがリストの最後に表示されます。",
