    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHERはTPスタジオの独立プロジェクトです。これはMinecraftの公式製品ではありませんし、Mojang、Microsoft、またはリンクされたコミュニティと認証または関連していません。",
    "Términos y condiciones": "利用規約",
    "Créditos y licencias de terceros": "第三者の著作権と許可",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric、Forge、OptiFine、Modrinth、CurseForgeは統合プロジェクトと提供者を識別します。ロゴと商標は、それぞれの保有者に属しています。これらはTPのオリジナルアートの一部ではありません。NeoForge: NeoForgedチーム · CC BY 4.0。Quilt: QuiltMC/art · CC0 1.0。Monocraft: Idrees Hassanと協力者 · SIL OFL 1.1。3Dビューアー: skinview3dとThree.js · MIT。",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11；公式ガイドラインに従って、ロゴを認証とリンクとして使用します。Microsoft、GitHub、Discordはそのサービスを識別します。これらは、それぞれの保有者に属しています。彼らの存在はスポンサーまたは関連性を暗示しません。",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "このCC BY 4.0およびCC0ライセンスは、指された素材の著作権を指し、商標権を除外します。著作権は特定の権利が適用される場合、認可を置き換えることはありません。",
