    "Organiza tus herramientas y prepara cada instalación a tu manera.": "ツールを整理し、各インストールを自分自身の方法で準備します。",
    "Abrir editor de HUD": "HUDエディタを開く",
    "seleccionados ·": "選択中 ·",
    "Overlay nativo TP": "ネイティブTPオーバーレイ",
    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "すべてのバージョンと互換性（バニラ/OptiFine/Forge用の通用オーバーレイ + FabricでのTP Companionとの拡張統合）。",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · ウィンドウまたは境界なし · 右Shift / F8でエディタを開きます。排他的なF11を使用している場合は、最初にウィンドウモードに戻ってください。",
    "Desactivar HUD universal": "ユニバーサルHUDを無効",
    "Activar HUD universal": "ユニバーサルHUDを有効",
    "Integración extendida · TP Companion": "拡張統合 · TPコンパニオン",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "リアルタイムHUD for FPS、座標、方向、防具、キー、ping、時間。一貫したHUDフォント、透明メニュー、Cキーでズーム、表面ミニマップ、チャットタイムスタンプを含む。",
    "Instalar el complemento TP al preparar una instancia compatible": "互換性のあるインスタンスを準備する際に、TP追加機能をインストールする",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "現在のアダプター: Fabric 1.21.1。その他のバージョンでは、ユニバーサルオーバーレイを使用。FPSと位置は起動時にTPブリッジに接続し、管理者権限なし。その他のデータの利用可能性はモジュールによって示されます。ミニマップとエンジン機能はTPコンパニオン互換である必要があります。",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "このインストールには追加機能が含まれていません。TP LAUNCHERを更新して有効化してください。",
    "Datos del juego": "ゲームデータ",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "接続器が準備完了しました。HUDをアクティベートしてからMinecraftを開く前に。",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "このインストールにはHUD接続器が含まれていません。TP LAUNCHERを更新してゲームデータを有効化してください。",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "TPからMinecraftを開始してデータを受け取ります。F8と右Shiftでエディタを開きます。",
    "Esperando partida": "ゲームを待っています",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "外部エフェクトは、著者の許可を得て次の起動に準備されています。TPはインストールして検証したJARファイルのみを有効または無効にします。コンテンツスタジオで手動追加したmodsを管理します。",
