    "Solo se equipan objetos con modelos y texturas locales de esta versión; siguen las manos y se incluyen en el PNG. Los recursos ausentes quedan ocultos.": "このバージョンのローカルモデルとテクスチャを持つオブジェクトのみが装備されます。手に取り付けられ、PNGに含まれます。欠落しているリソースは非表示になります。",
