    "Ir a": "移動到",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP APIは公開の無料のクエリカタログで、利用可能と使用制限に従います。応答がない場合は、TP APIから保存されたページのみが表示され、そのようなものとして識別されます。すべてのサーバーの通用的なレジストリは存在しません。",
