    "MyMemory traduce textos públicos en inglés. Sin conexión o al alcanzar el límite gratuito se muestra el original.": "MyMemory で公開された英語の文章を選択した言語に翻訳します。オフラインの場合や無料利用枠を超えた場合は原文を表示します。",
