    "Enlaces de": "リンクを",
    ", guardados localmente. No se conectan cuentas ni se verifica su titularidad.": ", 保存されています。アカウントは接続されておらず、所有権は確認されていません。",
    "Guardar perfil": "プロフィールを保存",
