    "Explora el launcher y observa al personaje de bienvenida. Cada descubrimiento aparecerá aquí.": "로처를 탐험하고 환영 캐릭터를 관찰하세요. 각 발견은 여기에 나타납니다.",
    "Prueba otra dificultad, categoría o un texto visible en las tarjetas.": "다른 난이도, 카테고리, 또는 카드에 보이는 텍스트를 시도하세요.",
