    "Mod externo: se prepara al iniciar una versión compatible. Sus opciones internas se ajustan en Minecraft.": "외부 mod: 호환 가능한 버전을 시작할 때 준비됩니다. Minecraft에서 자체 설정을 구성합니다.",
