    "para hacer zoom y suéltala para recuperar la vista normal. Funciona cuando el adaptador de esa versión está conectado.": "release로 정상 뷰로 복원합니다. 해당 버전의 어댑터가 연결되어 있어야 합니다.",
    "Se aplica dentro del juego cuando el conector o mod de esta edición lo permite. No es un widget que se coloque en pantalla.": "이 게임 내에서 지원되는 경우 연결기 또는 mod를 통해 적용됩니다. 이는 화면 위젯이 아닙니다.",
