    "Se aplica en vivo mediante los hooks de render compatibles. Los shaders que usan su propia niebla pueden requerir un adaptador específico.": "호환 가능한 렌더 훅을 통해 실시간으로 적용됩니다. shaders가 자체 안개를 사용하는 경우 특정 어댑터가 필요할 수 있습니다.",
    "TP Turbo · próximo inicio": "TP 터보 · 다음 시작",
    "Ajustes de recolección G1GC para Java 8 o superior": "Java 8 또는 이후 버전용 G1GC 가비지 컬렉션 설정",
    "Las optimizaciones seleccionadas se resuelven para la versión y el cargador exactos; al escoger una Release Vanilla con optimizadores activos se prepara una instalación Fabric independiente. No se promete un aumento fijo de FPS.": "선택한 최적화는 정확한 버전 및 로더에 대해 해결됩니다. Release 활성화된 Vanilla를 선택하면 독립적인 Fabric 설치를 준비합니다. 고정된 FPS 증가는 보장되지 않습니다.",
    "Gráficos y audio": "그래픽 및 오디오",
    "El brillo respeta el rango admitido por el juego; no se promete Fullbright con una opción que Minecraft limita.": " 밝기는 게임이 허용하는 범위 내에서 존중됩니다. Minecraft가 제한하는 옵션으로 Fullbright은 보장되지 않습니다.",
