    "Los atajos devuelven el foco al juego. Algunos no existen en versiones antiguas. La JVM puede ignorar una solicitud de memoria.": "단축키는 게임으로 초점을 돌립니다. 일부는 오래된 버전에서는 사용할 수 없습니다. JVM은 쓰레기 수집 요청을 무시할 수 있습니다.",
