    "TP LAUNCHER es un proyecto independiente de TP LABS. No es un producto oficial de Minecraft ni está aprobado o asociado con Mojang, Microsoft o las comunidades enlazadas.": "TP LAUNCHER은 TP 스토디오의 독립 프로젝트입니다. Minecraft의 공식 제품이 아니며 Mojang, Microsoft 또는 연결된 커뮤니티와 승인되거나 관련되어 있지 않습니다.",
    "Términos y condiciones": "약관 및 조건",
    "Créditos y licencias de terceros": "세부 정보 및 라이선스",
    "Fabric, Forge, OptiFine, Modrinth y CurseForge identifican los proyectos y proveedores integrados. Los logos y marcas pertenecen a sus respectivos titulares; no forman parte del arte original de TP. NeoForge: equipo NeoForged · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan y colaboradores · SIL OFL 1.1. Visor 3D: skinview3d y Three.js · MIT.": "Fabric, Forge, OptiFine, Modrinth, CurseForge는 통합 프로젝트 및 제공자를 식별합니다. 로고와 상표는 각각의 소유자에게 속해 있으며 TP의 원래 아트에 포함되지 않습니다. NeoForge: NeoForged 팀 · CC BY 4.0. Quilt: QuiltMC/art · CC0 1.0. Monocraft: Idrees Hassan 및 협력자 · SIL OFL 1.1. 3D 뷰어: skinview3d 및 Three.js · MIT.",
    "Blockbench: JannisX11; logo usado como crédito y enlace conforme a su guía pública. Microsoft, GitHub y Discord identifican sus servicios. Sus marcas pertenecen a sus titulares; su presencia no implica patrocinio ni afiliación.": "Blockbench: JannisX11; 공식 지침에 따라 로고를 사용하여 인증 및 링크합니다. Microsoft, GitHub 및 Discord는 그들의 서비스를 식별합니다. 그들의 상표는 그들의 소유자에게 속해 있으며 그들의 존재는 스폰서십이나 연합을 의미하지 않습니다.",
    "Las licencias CC BY 4.0 y CC0 aquí citadas se refieren a derechos de autor del material indicado y excluyen derechos de marca. Los créditos no sustituyen autorizaciones específicas que correspondan.": "여기서 언급된 CC BY 4.0 및 CC0 라이선스는 표시된 자료의 저작권을 의미하며 상표권을 제외합니다. 인증서는 특정 권한을 대체하지 않습니다.",
