    "Compatible con todas las versiones (Overlay Universal para Vanilla/OptiFine/Forge + Integración extendida con TP Companion en Fabric).": "모든 버전과 호환 (Vanilla/OptiFine/Forge + TP Companion와의 확장 통합 Fabric).",
    "Windows · Ventana o sin bordes · Shift derecho / F8 abre el editor. Si usas F11 exclusivo, vuelve primero al modo ventana.": "Windows · 창 또는 테두리 없음 · 오른쪽 Shift / F8으로 편집기 열림. 독점 F11을 사용 중이면 먼저 창 모드로 돌아갑니다.",
    "Desactivar HUD universal": "일반 HUD 비활성화",
    "Activar HUD universal": "일반 HUD 활성화",
    "Integración extendida · TP Companion": "확장 통합 · TP 동반자",
    "HUD real de FPS, coordenadas, dirección, armadura, teclas, ping y reloj. Incluye fuente uniforme para el HUD, menú transparente y zoom con C. Incluye minimapa de superficie y marcas horarias en el chat.": "실시간 HUD FPS, 좌표, 방향, 방어구, 키, 플레이어 지연, 시간. 일관된 HUD 글꼴, 투명 메뉴, C 키로 확대, 표면 미니맵 및 채팅 타임스탬프 포함.",
    "Instalar el complemento TP al preparar una instancia compatible": "호환 가능한 인스턴스를 준비할 때 TP 추가 기능 설치",
    "Adaptador actual: Fabric 1.21.1. En las demás versiones se usa el overlay universal. FPS y posición se conectan al iniciar mediante TP Bridge, sin permisos de administrador. La disponibilidad del resto de datos se indica por módulo; el minimapa y las funciones del motor necesitan TP Companion compatible.": "현재 어댑터: Fabric 1.21.1. 다른 버전에서는 일반 오버레이가 사용됩니다. FPS 및 위치는 시작 시 TP Bridge와 연결됩니다. 관리자 권한 없이. 다른 데이터의 사용 가능성은 모듈에 의해 표시됩니다. 미니맵 및 엔진 기능은 TP Companion 호환을 필요로 합니다.",
    "El complemento no está incluido en esta instalación. Actualiza TP LAUNCHER para habilitarlo.": "이 설치에는 추가 기능이 포함되어 있지 않습니다. TP LAUNCHER를 업데이트하여 활성화하세요.",
    "Datos del juego": "게임 데이터",
    "El conector está listo. Activa el HUD antes de abrir Minecraft.": "연결이 준비되었습니다. HUD를 활성화한 후 Minecraft를 열으세요.",
    "Esta instalación no incluye el conector del HUD. Actualiza TP LAUNCHER para habilitar los datos del juego.": "이 설치에는 HUD 연결기가 포함되어 있지 않습니다. TP LAUNCHER를 업데이트하여 게임 데이터를 활성화하세요.",
    "Inicia Minecraft desde TP para recibir datos. F8 y Shift derecho abren el editor.": "TP에서 데이터를 받으려면 Minecraft를 시작하세요. F8 및 오른쪽 Shift 키를 눌러 편집기를 엽니다.",
    "Esperando partida": "게임 대기 중",
    "Los efectos externos se preparan al siguiente inicio y conservan el crédito de sus autores. TP activa o desactiva solo los JAR que instaló y verificó; administra los mods añadidos manualmente desde el estudio de contenido.": "외부 효과는 다음 실행을 위해 준비되며, 그들의 저작권을 인정합니다. TP는 설치하고 검증한 JAR 파일만 활성화하거나 비활성화합니다. 콘텐츠 스튜디오에서 수동으로 추가한 mods를 관리하세요.",
