    ". Jugadores, icono y mensaje se consultan en la nube. La fecha de cada tarjeta indica la antigüedad del dato; «Medir ping» realiza una conexión TCP desde tu equipo solo cuando lo pulsas.": ". 플레이어, 아이콘, 메시지는 클라우드에서 확인됩니다. 각 카드 날짜는 데이터의 나이를 나타냅니다; «핑 측정»은 클릭할 때만 장치에서 TCP 연결을 수행합니다.",
