    "Ir a": "가기",
    "TP API es un catálogo público de consulta gratuita, sujeto a disponibilidad y límites de uso. Si no responde, solo se puede mostrar una página anterior guardada de TP API, identificada como tal. No existe un registro universal de todos los servidores.": "TP API는 사용 가능하고 사용량 제한에 따라 공개적이고 무료의 쿼리 카탈로그입니다. 응답이 없으면 TP API에서 이전에 저장된 페이지만 표시되며, 이는 특정한 서버를 나타냅니다. 모든 서버의 공용 등록이 없습니다.",
    "Se añaden a": "추가됨",
