    "Instalar Java recomendado": "권장 Java 설치",
    "Puedes omitir este paso. Podrás instalar Java más adelante al jugar o desde Ajustes.": "이 단계를 건너뛰실 수 있습니다. 게임을 할 때 또는 설정에서 나중에 Java를 설치할 수 있습니다.",
    "GB ·": "GB ·",
    "Jugar local sin conexión": "오프라인 플레이",
    "Perfil local sin cuenta Microsoft. No accede a servidores premium.": "Microsoft 계정 없이 로컬 프로필. 프리미엄 서버에 액세스하지 않습니다.",
    "Microsoft · Minecraft Premium": "Microsoft · Minecraft 프리미엄",
    "Tu cuenta, tu skin y tus capas oficiales.": "귀하의 계정, skin, 그리고 공식 캐프",
    "Nombre del jugador": "플레이어 이름",
    "El perfil local queda guardado en este equipo. No necesita contraseña.": "이 로컬 프로필은 이 기기에서 저장됩니다. 비밀번호가 필요하지 않습니다.",
    "Personalizar apariencia": "외관 사용자 정의",
